style.css:
@-moz-document domain("roblox.com") {
.content, .light-theme, .dark-theme, body {
        background-image: url("https://i.pinimg.com/736x/91/08/d4/9108d47e97793f21d3d69377c67624d3.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* Optional: Makes the standard UI visible so your background shows through */
    .content {
        background: visible !important;
    }
}
